create table if not exists public.settings(id bigint primary key,shop_name text not null default 'SBUYPRINT',tagline text not null default 'งานพิมพ์และสินค้าสำหรับร้านของคุณ',footer text not null default 'ขอบคุณที่อุดหนุนค่ะ/ครับ',logo text not null default '',phone text not null default '',line text not null default '',facebook text not null default '',email text not null default '',address text not null default '',qr_code text not null default '');
insert into public.settings(id) values(1) on conflict(id) do nothing;
alter table public.settings add column if not exists logo text not null default '';alter table public.settings add column if not exists phone text not null default '';alter table public.settings add column if not exists line text not null default '';alter table public.settings add column if not exists facebook text not null default '';alter table public.settings add column if not exists email text not null default '';alter table public.settings add column if not exists address text not null default '',qr_code text not null default '';
create table if not exists public.products(id bigint generated by default as identity primary key,category text not null,name text not null,price text not null default '',description text not null default '',image text not null default '',created_at timestamptz not null default now());
alter table public.settings enable row level security;alter table public.products enable row level security;
do $$ begin if not exists(select 1 from pg_policies where schemaname='public' and tablename='settings' and policyname='public read settings') then create policy "public read settings" on public.settings for select using(true);end if;if not exists(select 1 from pg_policies where schemaname='public' and tablename='products' and policyname='public read products') then create policy "public read products" on public.products for select using(true);end if;end $$;
